        liveMemberPredicate(),
      ),
    )
    .get();
  return row?.value ?? 0;
}

/**
 * The subset of `userIds` that hold a current membership in `orgId`. Fan-out
 * and assignment ask this instead of trusting the ids they were handed.
 */
export async function findCurrentMemberUserIds(
  orgId: OrgId,
  userIds: readonly UserId[],
): Promise<ReadonlySet<UserId>> {
  if (userIds.length === 0) return new Set();

  const rows = getDb()
    .select({ userId: members.userId })
    .from(members)
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        inArray(members.userId, [...userIds]),
        eq(members.status, "active"),
        liveMemberPredicate(),
      ),
    )
    .all();

  return new Set(rows.map((row) => brandId<UserId>(row.userId)));
}

export async function insertMember(
  orgId: OrgId,
  userId: UserId,
  role: Role,
  invitedBy: UserId | null,
): Promise<Member> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(members)
    .values({
      id: newId(),
      orgId,
      userId,
      role,
      status: "active",
      invitedBy,
      joinedAt: stamp,
      lastSeenAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toMember(row);
}

/**
 * Brings a former member back on the row the workspace already holds. The id,
 * `createdAt` and `lastSeenAt` survive, so whatever was recorded about them
 * stays attached; the role, inviter and join date come from the invitation.
 */
export async function reactivateMember(
  orgId: OrgId,
  memberId: MemberId,
  grant: {
    readonly role: Role;
    readonly invitedBy: UserId;
    readonly joinedAt: IsoTimestamp;
  },
): Promise<Member> {
  const row = getDb()
    .update(members)
    .set({
      archivedAt: null,
      status: "active",
      role: grant.role,
      invitedBy: grant.invitedBy,
      joinedAt: grant.joinedAt,
      updatedAt: grant.joinedAt,
    })
    .where(and(orgPredicate(members.orgId, orgId), eq(members.id, memberId)))
    .returning()
    .get();

  if (!row) throw new Error(`Member ${memberId} not found in org ${orgId}`);
  return toMember(row);
}

