vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { subscribe } from "@/lib/event-bus";
import { hashToken } from "@/lib/hash";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as digestService from "@/server/services/digest-service";
import * as invitationService from "@/server/services/invitation-service";
import * as issueService from "@/server/services/issue-service";
import * as memberService from "@/server/services/member-service";
import * as notificationService from "@/server/services/notification-service";
import * as projectService from "@/server/services/project-service";
import * as sessionService from "@/server/services/session-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

async function removeByUser(
  tenant: Awaited<ReturnType<typeof createTenant>>,
  userId: (typeof tenant.userIds)["viewer"],
) {
  const member = await memberRepo.findMember(tenant.org.id, userId);
  if (!member) throw new Error("fixture member missing");
  await memberService.removeMember(tenant.actors.owner, {
    orgId: tenant.org.id,
    memberId: member.id,
  });
  return member;
}

describe("former members", () => {
  it("a removed member gets no actor, even from a session minted before the removal", async () => {
    const tenant = await createTenant("fm-actor", "growth");
    const viewer = tenant.userIds.viewer;
    await removeByUser(tenant, viewer);

    await expect(memberService.resolveActor(viewer, tenant.org.id)).resolves.toBeNull();

    const principal = {
      userId: viewer,
      email: "viewer@fm-actor.test",
      activeOrgId: tenant.org.id,
      expiresAt: "2099-01-01T00:00:00.000Z",
    };
    await expect(
      sessionService.resolveActorForOrg(principal, tenant.org.slug),
    ).resolves.toBeNull();
    await expect(
      sessionService.switchActiveOrg(principal, { orgId: tenant.org.id } as never),
    ).rejects.toThrow(/not a member/);
  });

  it("refuses a second removal and a role change as conflicts, with no event and no seat change", async () => {
    const tenant = await createTenant("fm-conflict", "growth");
    const member = await removeByUser(tenant, tenant.userIds.viewer);
    const seatsBefore = await memberRepo.countActiveMembers(tenant.org.id);

    let removedEvents = 0;
    let roleEvents = 0;
    const offs: Unsubscribe[] = [
      subscribe("member.removed", () => {
        removedEvents += 1;
      }),
      subscribe("member.role_changed", () => {
        roleEvents += 1;
      }),
    ];

    await expect(
      memberService.removeMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: member.id,
      }),
    ).rejects.toThrow(/already archived/);
    await expect(
      memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: member.id,
        role: "admin",
      }),
    ).rejects.toThrow(/already archived/);

    for (const off of offs) off();
    expect(removedEvents).toBe(0);
    expect(roleEvents).toBe(0);
    await expect(memberRepo.countActiveMembers(tenant.org.id)).resolves.toBe(seatsBefore);

    const stored = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    expect(stored?.role).toBe("viewer");
  });

  it("unassigns issues and clears project leads on removal, and refuses new work for non-members", async () => {
    const tenant = await createTenant("fm-assign", "growth");
    const member = tenant.userIds.member;

    const extra = await projectService.createProject(tenant.actors.owner, {
      orgId: tenant.org.id,
      name: "fm-assign extra",
      slug: "extra",
      key: "FMX",
      description: null,
      visibility: "org",
      leadId: member,
      color: "#6366f1",
      targetDate: null,
    } as never);

    const issue = await issueService.createIssue(
      tenant.actors.admin,
      issueInput(tenant.org.id, tenant.project.id, { assigneeId: member }),
    );
    expect(issue.assigneeId).toBe(member);

    await removeByUser(tenant, member);

    const after = await issueRepo.findIssueById(tenant.org.id, issue.id);
    expect(after?.assigneeId).toBeNull();
    const afterProject = await projectRepo.findProjectById(tenant.org.id, extra.id);
    expect(afterProject?.leadId).toBeNull();

    const issuesBefore = await issueRepo.countIssues(tenant.org.id, tenant.project.id);

    await expect(
      issueService.assignIssue(tenant.actors.admin, {
        orgId: tenant.org.id,
        issueId: issue.id,
        assigneeId: member,
      }),
    ).rejects.toThrow(/was not found/);

    await expect(
      issueService.createIssue(
        tenant.actors.admin,
        issueInput(tenant.org.id, tenant.project.id, { assigneeId: member }),
      ),
    ).rejects.toThrow(/was not found/);
    await expect(issueRepo.countIssues(tenant.org.id, tenant.project.id)).resolves.toBe(
      issuesBefore,
    );

    await expect(
      projectService.createProject(tenant.actors.owner, {
        orgId: tenant.org.id,
        name: "fm-assign second",
        slug: "second",
        key: "FMY",
        description: null,
        visibility: "org",
        leadId: member,
        color: "#6366f1",
        targetDate: null,
      } as never),
    ).rejects.toThrow(/was not found/);

    await expect(
      projectService.updateProject(tenant.actors.owner, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        leadId: member,
      }),
    ).rejects.toThrow(/was not found/);

    const stillLead = await projectRepo.findProjectById(tenant.org.id, tenant.project.id);
    expect(stillLead?.leadId).toBe(tenant.userIds.owner);
  });

  it("does not notify a former member or list them as a digest recipient", async () => {
    const tenant = await createTenant("fm-notify", "growth");
    const viewer = tenant.userIds.viewer;
    const admin = tenant.userIds.admin;

    for (const userId of [viewer, admin]) {
      await preferenceRepo.upsertPreference({
        orgId: tenant.org.id,
        userId,
        kind: "comment_created",
        inApp: true,
        email: true,
        digestOnly: true,
      } as never);
    }

    await removeByUser(tenant, viewer);

    const rows = await notificationService.notify(tenant.org.id, "comment_created", [viewer], {
      title: "New comment",
      body: "body",
      href: "/issues/x",
      actorId: tenant.userIds.owner,
    });
    expect(rows).toHaveLength(0);

    const recipients = await digestService.listDigestRecipients(tenant.org.id);
    expect(recipients).toContain(admin);
    expect(recipients).not.toContain(viewer);

    const bundle = await digestService.buildDigest(
      tenant.org.id,
      viewer,
      "2000-01-01T00:00:00.000Z" as never,
      "2099-01-01T00:00:00.000Z" as never,
    );
    expect(bundle).toBeNull();
  });

  it("re-admits a former member on the same row, with the invitation's role and inviter, listed once", async () => {
    const tenant = await createTenant("fm-rejoin", "growth");
    const viewer = tenant.userIds.viewer;
    const orgId = tenant.org.id;
    const before = await removeByUser(tenant, viewer);
    const seatsAfterRemoval = await memberRepo.countActiveMembers(orgId);

    const token = "d".repeat(32);
    await invitationRepo.insertInvitation(
      orgId,
      { orgId, email: "viewer@fm-rejoin.test", role: "admin", expiresInDays: 14 },
      tenant.userIds.owner,
      hashToken(token),
    );

    const joined: unknown[] = [];
    const off = subscribe("member.joined", (payload) => {
      joined.push(payload);
    });
    const member = await invitationService.acceptInvitation(viewer, { token });
    off();

    expect(member.id).toBe(before.id);
    expect(member.status).toBe("active");
    expect(member.archivedAt).toBeNull();
    expect(member.role).toBe("admin");
    expect(member.invitedBy).toBe(tenant.userIds.owner);
    expect(member.joinedAt).not.toBeNull();
    expect(member.createdAt).toBe(before.createdAt);
    expect(joined).toHaveLength(1);

    await expect(memberRepo.countActiveMembers(orgId)).resolves.toBe(seatsAfterRemoval + 1);

    const orgs = await orgRepo.listOrgsForUser(viewer);
    expect(orgs.map((org) => org.id)).toContain(orgId);

    await expect(memberService.resolveActor(viewer, orgId)).resolves.toMatchObject({
      role: "admin",
    });

    const page = await memberRepo.listMembers({ orgId, limit: 100, cursor: null });
    expect(page.items.filter((row) => row.userId === viewer)).toHaveLength(1);

    await expect(
      invitationService.acceptInvitation(viewer, { token }),
    ).rejects.toThrow(/already been accepted/);
  });

  it("spends an invitation accepted by a current member without changing them", async () => {
    const tenant = await createTenant("fm-current-accept", "growth");
    const admin = tenant.userIds.admin;
    const orgId = tenant.org.id;
    const token = "e".repeat(32);
    const invitation = await invitationRepo.insertInvitation(
      orgId,
      { orgId, email: "admin@fm-current-accept.test", role: "viewer", expiresInDays: 14 },
      tenant.userIds.owner,
      hashToken(token),
    );
    const before = await memberRepo.findMember(orgId, admin);

    const member = await invitationService.acceptInvitation(admin, { token });

    expect(member.id).toBe(before?.id);
    expect(member.role).toBe("admin");
    expect(member.joinedAt).toBe(before?.joinedAt);
    await expect(memberRepo.countActiveMembers(orgId)).resolves.toBe(4);
    await expect(invitationRepo.countPendingInvitations(orgId)).resolves.toBe(0);
    const pending = await invitationRepo.listPendingInvitations(orgId);
    expect(pending.find((row) => row.id === invitation.id)).toBeUndefined();

    await expect(invitationService.acceptInvitation(admin, { token })).rejects.toThrow(
      /already been accepted/,
    );
  });

  it("leaves a former member's memberships in other workspaces untouched", async () => {
    const first = await createTenant("fm-other-a", "growth");
    const second = await createTenant("fm-other-b", "growth");
    const viewer = first.userIds.viewer;

    await memberRepo.insertMember(second.org.id, viewer, "member", null);

    await removeByUser(first, viewer);

    await expect(memberService.resolveActor(viewer, first.org.id)).resolves.toBeNull();
    await expect(memberService.resolveActor(viewer, second.org.id)).resolves.toMatchObject({
      role: "member",
    });
    const orgs = await orgRepo.listOrgsForUser(viewer);
    expect(orgs.map((org) => org.id)).toContain(second.org.id);
  });
});

